// Reject what a retry could never fix, BEFORE the API call.
//
// n8n's retry engine fires on any error and cannot filter by status code
// (verified in the docs and by hand). That means a malformed body would be
// retried three times and still fail with 400 - three times the noise for no
// chance of success. Validation here is what keeps the retry meaningful.
const o = $json.body || $json || {};

const problems = [];
if (!o.order_id) problems.push('order_id missing');
if (!o.email || !String(o.email).includes('@')) problems.push('email missing or invalid');
if (typeof o.amount !== 'number' || !isFinite(o.amount) || o.amount <= 0) {
  problems.push('amount must be a positive number');
}

return [{
  json: {
    valid: problems.length === 0,
    problems,
    order_id: o.order_id || null,
    payload: o,
    // The idempotency key is derived once, here, so a retry cannot change it.
    idem_key: o.order_id ? `order:${o.order_id}` : null,
  },
}];

// Never sent to the API, so the retry budget is not spent on it.
return [{ json: { ok: false, rejected_before_send: true,
  problems: $json.problems, order_id: $json.order_id } }];

return [{
  json: {
    ok: true,
    order_id: $json.order_id || ($json.body ? $json.body.order_id : null),
    recorded_at: new Date().toISOString(),
    note: 'written once; a repeated delivery updates the same row on idem_key',
  },
}];

// Decide whether another attempt could plausibly work.
//
// 429, 408 and 5xx are the server saying "later" - worth waiting.
// Any other 4xx is the server saying "never" - retrying is waste.
//
// n8n's retry engine catches every error and cannot filter by status code
// (workflow-execute.ts, v2.48.6: `catch (error)` with no type check), so the
// decision has to live here instead of in retryOnFail.
const err = $json.error || {};
const code = Number(err.httpCode || err.statusCode || err.status || 0);

// The error output carries ONLY `error`, so the order is read back from the
// node that produced it. Trusting $json.payload here silently sent null
// downstream and broke the "original payload is kept" promise.
const src = $('Validate order').first().json;

let kelas = 'PERMANENT';
if (code === 429 || code === 408 || code >= 500 || code === 0) kelas = 'TEMPORARY';

// Exactly one retry stage exists downstream, so one fixed wait is all this
// workflow can express. n8n clamps waitBetweenTries to 5000 ms, which is why
// the wait is a real Wait node instead of a retryOnFail setting.
const backoff = 5;

return [{
  json: {
    class: kelas,
    http_code: code,
    attempt: 1,
    backoff_seconds: backoff,
    retryable: kelas === 'TEMPORARY',
    message: String(err.message || '').slice(0, 200),
    payload: src.payload || null,
    idem_key: src.idem_key || null,
    order_id: src.order_id || null,
  },
}];

// Reached from two different places, so both shapes must land here:
//   * Retryable? out 1        - classification present, no retry allowed
//   * Send to CRM (after backoff) error output - carries only `error`
// In the second case the classification is read back from the classifier;
// without that, class/http_code/idem_key were all undefined.
const cameFromRetryStage = !$json.class;
const cls = cameFromRetryStage ? ($('Classify failure').first().json || {}) : $json;
const err = $json.error || {};

const attempts = cameFromRetryStage ? (cls.attempt || 1) + 1 : (cls.attempt || 1);

return [{
  json: {
    ok: false,
    class: cls.class || 'PERMANENT',
    http_code: cls.http_code !== undefined && cls.http_code !== null
      ? cls.http_code
      : Number(err.httpCode || err.statusCode || 0),
    attempts,
    idem_key: cls.idem_key || null,
    order_id: cls.order_id || null,
    payload_kept: cls.payload !== null && cls.payload !== undefined,
    recorded_at: new Date().toISOString(),
    note: 'kept for replay; nothing was written to the CRM',
  },
}];
